public class AgentRunOptions
{
    public AgentRunOptions();
    public AgentRunOptions(AgentRunOptions options);  // Copy constructor

    // Properties
    public string? ContinuationToken { get; set; }
    public bool AllowBackgroundResponses { get; set; }
    public IDictionary<string, object> AdditionalProperties { get; set; }
    public ChatResponseFormat? ResponseFormat { get; set; }

    public virtual AgentRunOptions Clone();
}
```

**Specialized Class for ChatClientAgent:**
```csharp
namespace Microsoft.Agents.AI;

public class ChatClientAgentRunOptions : AgentRunOptions
{
    // Constructor with ChatOptions
    public ChatClientAgentRunOptions(Microsoft.Extensions.AI.ChatOptions? chatOptions);

    // Copy constructor
    public ChatClientAgentRunOptions(ChatClientAgentRunOptions options);

    // Properties
    public Microsoft.Extensions.AI.ChatOptions? ChatOptions { get; set; }
