    chatClient: client,
    instructions: "...",
    name: "MyAgent",
    description: "...",
    tools: tools,
    loggerFactory: null,
    services: null);
```

#### **Option B: Use ChatClientAgentRunOptions.ChatOptions**
```csharp
var runOptions = new ChatClientAgentRunOptions(
    new Microsoft.Extensions.AI.ChatOptions 
    { 
        Tools = new List<AITool> { ... }
    });

await agent.RunAsync("message", session, runOptions, cancellationToken);
```

