+        ? throw new InvalidOperationException("No topic provided.")
+        : input;
+}
+
+static async Task<string> WebSearchAsync(HttpClient httpClient, string query)
+{
+    // Uses the DuckDuckGo Instant Answer API (free, no key required)
+    var encoded = Uri.EscapeDataString(query);
+    var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
