 using System.ComponentModel;
 using System.Net.Http.Json;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // --- Configuration -----------------------------------------------------------

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 // --- Tool definitions --------------------------------------------------------

 var notebook = new ResearchNotebook();
 using var httpClient = new HttpClient();

 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(
         ([Description("The search query to look up on the web")] string query) =>
             WebSearchAsync(httpClient, query),
         "web_search",
         "Search the web for information on a topic. Returns a list of result titles, URLs, and snippets."),

     AIFunctionFactory.Create(
         ([Description("A heading or label for the note")] string title,
          [Description("The content to save")] string content) =>
         {
             notebook.Add(title, content);
             return $"Note saved: \"{title}\" ({content.Length} chars)";
         },
         "save_note",
         "Save a research note. Use this to record important findings as you research."),

     AIFunctionFactory.Create(
         () => notebook.GetAll(),
         "read_notes",
         "Read all notes saved so far. Use this to review what you have collected before writing a summary."),
 };

 // --- Agent setup -------------------------------------------------------------

 var openAiClient = new OpenAIClient(apiKey);
 IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

 var agent = new ChatClientAgent(
     chatClient: chatClient,
     instructions: """
         You are a research agent. Given a topic, you perform thorough web research
         and produce a well-organized summary.

         Workflow:
         1. Break the topic into 2-3 focused search queries.
         2. For each query, call web_search and review the results.
         3. Save the most important findings using save_note.
         4. After gathering enough information, call read_notes to review everything.
         5. Produce a final, well-structured summary with key findings and sources.

         Be concise but thorough. Cite sources where possible.
         """,
     name: "ResearchAgent",
     description: "An agent that researches topics using web search and note-taking",
     tools: tools,
     loggerFactory: null,
     services: null);

 // --- Run the agent -----------------------------------------------------------

 var topic = args.Length > 0
     ? string.Join(' ', args)
     : PromptUser("Enter a research topic: ");

 Console.WriteLine($"\n🔍 Researching: {topic}\n");

 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 4096,
 });

 await foreach (var update in agent.RunStreamingAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}",
     session: null,
     runOptions,
     CancellationToken.None))
 {
     if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
     {
         Console.Write(update.Text);
     }
 }

 Console.WriteLine();

 // --- Helper methods ----------------------------------------------------------

 static string PromptUser(string prompt)
 {
     Console.Write(prompt);
     var input = Console.ReadLine()?.Trim();
     return string.IsNullOrWhiteSpace(input)
         ? throw new InvalidOperationException("No topic provided.")
         : input;
 }

 static async Task<string> WebSearchAsync(HttpClient httpClient, string query)
 {
     // Uses the DuckDuckGo Instant Answer API (free, no key required)
     var encoded = Uri.EscapeDataString(query);
     var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

     try
     {
         var doc = await httpClient.GetFromJsonAsync<JsonDocument>(url);
         if (doc is null)
             return "No results found.";

         var results = new List<string>();

         // Abstract (main topic summary)
         var abstractText = doc.RootElement.GetProperty("AbstractText").GetString();
         var abstractUrl = doc.RootElement.GetProperty("AbstractURL").GetString();
         if (!string.IsNullOrWhiteSpace(abstractText))
         {
             results.Add($"**Summary**: {abstractText}\nSource: {abstractUrl}");
         }

         // Related topics
         if (doc.RootElement.TryGetProperty("RelatedTopics", out var related))
         {
             foreach (var topic in related.EnumerateArray().Take(5))
             {
                 var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                 var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                 if (!string.IsNullOrWhiteSpace(text))
                 {
                     results.Add($"- {text}\n  URL: {link}");
                 }
             }
         }

         return results.Count > 0
             ? string.Join("\n\n", results)
             : $"No detailed results for \"{query}\". Try a more specific query.";
     }
     catch (Exception ex)
     {
         return $"Search failed: {ex.Message}";
     }
 }

 // --- Notebook class ----------------------------------------------------------

 sealed class ResearchNotebook
 {
     private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

     public string Add(string title, string content)
     {
         _notes.Add((title, content, DateTime.UtcNow));
         return $"Saved note #{_notes.Count}: {title}";
     }

     public string GetAll()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         return string.Join("\n\n", _notes.Select((n, i) =>
             $"--- Note #{i + 1}: {n.Title} ---\n{n.Content}"));
     }
 }

